function states.parse_fabric_payload_header(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 43 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_fabric_payload_header = tree:add(pf.f_hdr_fabric_payload_header, buf(math.floor(off / 8)))
  if off + 16 > avail then
    hdr_fabric_payload_header:add_proto_expert_info(ef_error, "out of bounds in fabric_payload_header.ether_type")
    return off
  end
  v.v_fabric_payload_header_ether_type = buf():bitfield(off, 16)
  hdr_fabric_payload_header:add(pf.f_fabric_payload_header_ether_type, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), v.v_fabric_payload_header_ether_type)
  off = off + 16
  if bit32.band(v.v_fabric_payload_header_ether_type, 65024) == 0 then
    return states.parse_llc_header(buf, pinfo, tree, off, depth)
  elseif bit32.band(v.v_fabric_payload_header_ether_type, 64000) == 0 then
    return states.parse_llc_header(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 33024 then
    return states.parse_vlan(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 37120 then
    return states.parse_qinq(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 34887 then
    return states.parse_mpls(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 2048 then
    return states.parse_ipv4(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 34525 then
    return states.parse_ipv6(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 2054 then
    return states.parse_arp_rarp(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 35020 then
    return states.parse_set_prio_high(buf, pinfo, tree, off, depth)
  elseif v.v_fabric_payload_header_ether_type == 34825 then
    return states.parse_set_prio_high(buf, pinfo, tree, off, depth)
  else
    add_payload(buf, tree, off)
    return off
  end
end

function states.parse_set_prio_med(buf, pinfo, tree, off, depth)
  depth = depth + 1
